#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 8

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);

int getResult(int row, int col, int matrix[MAX_SIZE][MAX_SIZE]);

int main() {
    int matrix[MAX_SIZE][MAX_SIZE];

    int row = 0;
    int col = 0;

    char s[1000];
    while(gets(s)) {
        // 本地测试可以开启此行
        // if(strlen(s) == 0) break;

        col = 0;
        char* token = strtok(s, " ");
        while(token != NULL) {
            // YES 简化为 0, NO 简化为 1, NA 简化为 2
            if(strcmp("YES", token) == 0) {
                matrix[row][col] = 0;
            } else if(strcmp("NO", token) == 0) {
                matrix[row][col] = 1;
            } else {
                matrix[row][col] = 2;
            }

            token = strtok(NULL, " ");
            col++;
        }
        row++;
    }

    printf("%d\n", getResult(row, col, matrix));

    return 0;
}

int getResult(int row, int col, int matrix[MAX_SIZE][MAX_SIZE]) {
    // 记录宜居区坐标位置
    LinkedList *queue = new_LinkedList();

    // 记录可改造区数量
    int need = 0;

    for (int i = 0; i < row; i++) {
        for (int j = 0; j < col; j++) {
            switch (matrix[i][j]) {
                case 0:
                    addLast_LinkedList(queue, i * col + j);
                    break;
                case 1:
                    need++;
                    break;
            }
        }
    }

    // 如果没有宜居区，则无法改造，直接返回-1
    if (queue->size == 0) return -1;
    // 如果全是宜居区，则无需改造，直接返回0
    if (queue->size == row * col) return 0;

    // 记录花费的天数
    int day = 0;

    // 上，下，左，右四个方向的偏移量
    int offsets[4][2] = {{-1, 0},
                         {1,  0},
                         {0,  -1},
                         {0,  1}};

    // 图的多源BFS模板
    while (queue->size > 0 && need > 0) {
        LinkedList *newQueue = new_LinkedList();

        ListNode *cur = queue->head;
        while (cur != NULL) {
            int x = cur->ele / col;
            int y = cur->ele % col;

            // 上，下，左，右四个方向扩散
            for (int i = 0; i < 4; i++) {
                int newX = x + offsets[i][0];
                int newY = y + offsets[i][1];

                // 如果新位置没有越界，且为NO，则可以被改造
                if (newX >= 0 && newX < row && newY >= 0 && newY < col && matrix[newX][newY]== 1) {
                    matrix[newX][newY] = 0;
                    addLast_LinkedList(newQueue, newX * col + newY);
                    need--;
                }
            }

            cur = cur->next;
        }

        day++;
        queue = newQueue;
    }

    if (need == 0) {
        return day;
    } else {
        return -1;
    }
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
